SPF30という数値は、真夏の炎天下でのマリンスポーツなどには物足りないかもしれませんが、通勤や買い物、ちょっとした外出といった日常使いには最適です。肌への負担を最小限に抑えつつ、しっかりと紫外線をブロックしてくれるバランスの良さは見事。メイクをする男性にとっては、化粧下地としても優秀で、ファンデーションのノリと持ちが格段に向上しました。

使用のコツとしては、少量ずつ重ねて塗るよりも、推奨量を一度に顔全体に広げ、ムラなく馴染ませるのが効果的です。特に汗をかきやすい季節は、こまめに塗り直すことで、より高い効果を実感できます。日中の乾燥が気になる場合は、上から保湿スプレーを軽く吹きかけるのも良いでしょう。

