さらに、汗のニオイに関しても嬉しい変化がありました。肌が常に清潔に保たれている感覚があり、汗をかいた後の不快なニオイが軽減されたように感じます。これは、肌の表面環境が整うことで、雑菌の繁殖が抑えられた結果かもしれません。

敏感肌への配慮も特筆すべき点です。私は季節の変わり目や強い日差しで肌が敏感に傾くことがありますが、アルコールフリー処方のおかげか、30日間一度も刺激や赤み、かゆみを感じることなく使用できました。これなら、肌がデリケートな時でも安心して毎日使えるでしょう。

