    features: [`唇にハリとツヤを与えるプランプ効果`, `乾燥や荒れを防ぐ高保湿ケア`, `ベタつきにくい軽やかなテクスチャー`, `敏感な唇にも配慮した処方`],
    pros: [`マスク着用時も快適な自然なツヤと潤い`, `縦ジワを目立たなくし、ふっくらとした印象に`, `日中の乾燥対策からナイトケアまで対応する汎用性`],
