    introText: `夏の猛烈な暑さ、汗と皮脂でドロドロになる肌。夕方にはもう諦めている方も多いのではないでしょうか。今回は、その悩みを根本から解決する一本を、30日間の徹底検証で深掘りします。`,
    features: [`「超オイリー肌」に特化した強力な皮脂吸着成分配合`, `汗や水に強く、テカリ・ベタつきを長時間抑制`, `軽いつけ心地で、毛穴の目立ちにくいサラサラ肌をキープ`],
    pros: [`圧倒的な皮脂崩れ防止力で、日中のテカリやベタつきが激減`, `マスク着用時の蒸れや擦れにも強く、メイクよれを最小限に抑える`],
