検証の肝となるのは、やはり日中の持続力でした。猛暑日でも、朝8時に塗布して夕方18時まで、日焼け止め効果が持続しているのを実感。汗をかいても、顔がドロドロになったり、日焼け止めが白く浮き出たりする現象は皆無でした。肌を触ってもサラッとした感触が続き、テカリも普段より大幅に抑制されていることに感動。これは「スーパーウォータープルーフ」と「フリクションプルーフ」という摩擦に強い技術の賜物だと確信しました。マスクとの摩擦が多い頬や鼻周りも、日焼け止めがヨレることなく、夕方までしっかりと肌を守ってくれていました。

