また、敏感肌の私にとって、肌への刺激がないかどうかも重要なポイントでした。これまで多くのデオドラント製品で経験してきた、塗布後のヒリつきやかゆみは、このリフレアでは一度も感じませんでした。カミソリ負けをしてデリケートになっている肌に塗っても、刺激は皆無。肌に優しい処方であるという謳い文句は、まさに偽りなしでした。

