    features: [`瞬時に肌を冷却するフローズンミントの爽快感`, `汗とニオイを抑えるデオドラント効果`, `サラサラ肌をキープするパウダーイン処方`],
    pros: [`炎天下でも即座に体感できる圧倒的なクールダウン効果と持続性。`, `夕方まで汗とニオイを気にせず、清潔感を保てる確かなデオドラント力。`, `肌荒れしやすい敏感肌でも刺激を感じにくい優しい使用感。`],
