また、特筆すべきは、この強力なフローズンミントでありながら、私の肌には刺激が少なかった点だ。デリケートな時期でも赤みやかゆみを感じることはなく、敏感肌の人でも比較的安心して使えるだろう。ただし、デメリットとして挙げたように、スプレー直後のメントール感は非常に強い。特に塗布量が多かったり、顔に近い部分に直接スプレーしたりすると、刺激が目に染みたり、肌がピリピリしたりすることがあった。この点は、使用量を調整し、塗布する部位を選ぶことで解決できる。例えば、首筋や腕、背中など、広範囲にわたって数回に分けて塗布することで、刺激を抑えつつ全体を効果的にクールダウンできる。

