以前は夕方になると、ふと自分のニオイが気になっていたのですが、ソフトストーンWを使い始めてからは、その不安から解放されました。電車での移動中や会議室など、密閉された空間でも自信を持って過ごせるようになったのは、精神的にも大きな変化です。
